const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.bookmark}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=(id,w=800)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const categories=['美食','景點','住宿','活動'],catIcons={美食:'food',景點:'mountain',住宿:'bed',活動:'spark'};
const cities=['臺北市','新北市','基隆市','桃園市','新竹市','新竹縣','苗栗縣','臺中市','彰化縣','南投縣','雲林縣','嘉義市','嘉義縣','臺南市','高雄市','屏東縣','宜蘭縣','花蓮縣','臺東縣','澎湖縣','金門縣','連江縣'];
const seed=[
{id:1,name:'小院子・日光咖啡',city:'宜蘭縣',district:'宜蘭市',cats:['美食'],note:'窗邊的位子超舒服，下次一起來吃草莓蛋糕！',image:photo('photo-1442512595331-e89e73853f31'),author:'小芸',date:'11/12',address:'宜蘭縣宜蘭市（示範地點）',notes:[{name:'小芸',text:'窗邊的位子超舒服，下次一起來吃草莓蛋糕！'}],links:['https://www.facebook.com/'],visited:false,again:true},
{id:2,name:'見晴懷古步道',city:'宜蘭縣',district:'大同鄉',cats:['景點'],note:'想走走被森林包圍的舊鐵道，雨後更有氣氛。',image:photo('photo-1448375240586-882707db888b'),author:'阿哲',date:'11/11',address:'宜蘭縣大同鄉太平山',notes:[{name:'阿哲',text:'想走走被森林包圍的舊鐵道，雨後更有氣氛。'}],links:['https://www.google.com/search?q=見晴懷古步道'],visited:false},
{id:3,name:'海邊邊・慢日子民宿',city:'花蓮縣',district:'壽豐鄉',cats:['住宿'],note:'醒來就看得到海，留給下次的東海岸小旅行。',image:photo('photo-1613490493576-7fde63acd811'),author:'怡君',date:'11/10',address:'花蓮縣壽豐鄉（示範地點）',notes:[{name:'怡君',text:'醒來就看得到海，留給下次的東海岸小旅行。'}],links:[],visited:false},
{id:4,name:'正好鮮肉小籠包',city:'宜蘭縣',district:'宜蘭市',cats:['美食'],note:'大家都說要早點去，想吃爆汁的三星蔥小籠包。',image:photo('photo-1563245372-f21724e3856d'),author:'小芸',date:'11/09',address:'宜蘭縣宜蘭市',notes:[{name:'小芸',text:'大家都說要早點去，想吃爆汁的三星蔥小籠包。'}],links:[],visited:true,again:true},
{id:5,name:'草嶺古道・芒花季',city:'新北市',district:'貢寮區',cats:['景點','活動'],note:'秋天的芒花和海景，找個好天氣一起出發。',image:photo('photo-1464822759023-fed622ff2c3b'),author:'阿哲',date:'11/08',address:'新北市貢寮區草嶺古道',notes:[{name:'阿哲',text:'秋天的芒花和海景，找個好天氣一起出發。'}],links:[],visited:false},
{id:6,name:'巷弄裡的甜・草莓冰',city:'臺南市',district:'中西區',cats:['美食'],note:'草莓冰先存起來，等草莓季再來踩點。',image:photo('photo-1563805042-7684c019e1cb'),author:'怡君',date:'11/07',address:'臺南市中西區（示範地點）',notes:[{name:'怡君',text:'草莓冰先存起來，等草莓季再來踩點。'}],links:[],visited:false},
{id:7,name:'週末台中口袋名單（待整理）',city:'臺中市',district:'',cats:[],note:'貼文裡有三家店，之後再慢慢整理。',author:'你',date:'11/13',pending:true,notes:[],links:['https://www.facebook.com/'],visited:false}
];
let saved;try{saved=JSON.parse(localStorage.getItem('pocket-daily-v1'))}catch{};
let data=saved?.places||seed,requests=saved?.requests??['小安'],updates=saved?.updates||[{text:'小芸收藏了「小院子・日光咖啡」',date:'昨天 16:32'},{text:'阿哲在「見晴懷古步道」留下了備註',date:'11/11 20:15'},{text:'怡君加入了週末出走計畫',date:'11/10 12:08'}];
let state={page:'all',category:'全部',city:'',district:'',q:'',sort:'new',view:'grid'},current=null;
const persist=()=>{try{localStorage.setItem('pocket-daily-v1',JSON.stringify({places:data,requests,updates}))}catch{toast('瀏覽器無法儲存資料，請保留此頁面。')}};
const addUpdate=text=>{updates.unshift({text,date:'剛剛'});persist()};
let toastTimer;function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
const navItems=[['all','bookmark','所有收藏'],['pending','clock','待補資料'],['again','heart','想再去'],['members','people','共用成員'],['updates','spark','最近更新']];
function navHtml(mobile=false){return navItems.filter(x=>!mobile||x[0]!=='again').map(([id,ic,label])=>`<button class="${state.page===id?'active':''}" data-nav="${id}">${icon(ic)}<span>${label}</span>${!mobile&&id==='pending'?`<em>${data.filter(p=>p.pending).length}</em>`:''}${!mobile&&id==='members'&&requests.length?`<em>${requests.length}</em>`:''}</button>`).join('')}
function render(){document.getElementById('app').innerHTML=`<aside><a class="brand" href="#" aria-label="口袋日常首頁"><span class="brand-icon">${icon('bookmark')}</span><span>口袋日常<small>POCKET DAYS</small></span></a><div class="workspace"><span class="badge">🌿</span><div><b>週末出走計畫</b><br><small>我們的共用清單 · 4 位成員</small></div></div><div class="nav-label">OUR COLLECTION</div><nav>${navHtml()}</nav><div class="side-note">${icon('leaf')}<b>美好的地方，慢慢收集。</b>把偶然心動的瞬間，<br>留給下一次一起出發。</div><button class="user" id="profile"><span class="avatar">你</span><span>你的口袋<small>清單管理員 · 示範模式</small></span>${icon('chevron')}</button></aside><main><header class="topbar"><div class="mobile-brand"><span class="brand-icon">${icon('bookmark')}</span>口袋日常</div><div class="crumb">我們的共用清單 <span>/</span><span>週末出走計畫</span></div><div class="top-actions"><div class="avatars" aria-label="共用清單成員"><span class="avatar">芸</span><span class="avatar">哲</span><span class="avatar">君</span><span class="avatar">你</span></div><button class="invite" id="invite">${icon('people')} 邀請朋友</button></div></header><div class="content" id="content"></div></main><div class="mobile-nav">${navHtml(true)}<button id="mobile-profile">${icon('bookmark')}我的</button></div>`;
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.page=b.dataset.nav;state.q='';state.category='全部';state.city='';state.district='';render()});document.querySelector('.brand').onclick=e=>{e.preventDefault();state.page='all';render()};document.getElementById('invite').onclick=inviteModal;document.getElementById('profile').onclick=profileModal;document.getElementById('mobile-profile').onclick=profileModal;
if(['all','pending','again'].includes(state.page))renderCollection();else if(state.page==='members')renderMembers();else renderUpdates()}
function renderCollection(){let pending=state.page==='pending',again=state.page==='again';document.getElementById('content').innerHTML=`${!pending&&!again?`<section class="hero"><div class="hero-photo"></div><div class="hero-copy"><div class="eyebrow">GOOD PLACES, BETTER TOGETHER</div><h1>把想去的，<br>放在一起。</h1><p>一篇貼文、一家小店、一段風景。<br>和喜歡的人，慢慢收集下一次出發的理由。</p><button class="hero-link" id="hero-add">收藏今天的心動 ${icon('arrow')}</button></div><span class="photo-label">${icon('pin')} 下一站，往山裡走走</span></section>`:`<div class="page-intro"><div class="eyebrow">${pending?'SAVE NOW, SORT LATER':'SOME PLACES STAY WITH YOU'}</div><h1>${pending?'先存起來，慢慢整理。':'值得，再去一次。'}</h1><p>${pending?'來不及整理也沒關係，心動的連結都在這裡。':'那些去過以後，還想一起回去的地方。'}</p></div>`}<div class="section-head"><div><h2>${pending?'待補資料':again?'我的想再去':'我們的口袋清單'}<span class="subtitle-count">${data.filter(p=>pending?p.pending:again?p.again:!p.pending).length}</span></h2><p>${pending?'補上地點、分類，就能加入出走計畫':again?'只顯示你自己的想再去紀錄':'各自發現，一起收藏。好去處都在這裡。'}</p></div><button class="primary" id="add">${icon('plus')} 新增收藏</button></div><section class="filters"><div class="filter-top"><label class="search">${icon('search')}<input id="search" placeholder="搜尋地點、備註，例如：草莓冰" value="${esc(state.q)}" aria-label="搜尋地點及備註"></label><div class="region"><select id="city" aria-label="縣市"><option value="">所有縣市</option>${cities.map(c=>`<option ${state.city===c?'selected':''}>${c}</option>`).join('')}</select><select id="district" aria-label="鄉鎮市區"></select></div></div><div class="filter-bottom"><div class="tabs">${['全部',...categories].map(c=>`<button data-cat="${c}" class="${state.category===c?'active':''}">${icon(c==='全部'?'grid':catIcons[c])}${c==='全部'?'全部收藏':c}</button>`).join('')}</div></div></section><div class="resultbar"><span id="count"></span><div class="view-toggle"><select class="sort" id="sort" aria-label="排序方式"><option value="new">最近收藏</option><option value="name">名稱排序</option></select><button data-view="grid" aria-label="網格檢視" class="${state.view==='grid'?'active':''}">${icon('grid')}</button><button data-view="list" aria-label="列表檢視" class="${state.view==='list'?'active':''}">${icon('list')}</button></div></div><div class="grid ${state.view==='list'?'list':''}" id="cards"></div><div class="footline">${icon('leaf')} 好的風景，值得一起收藏。慢慢存，慢慢去。</div>`;
document.getElementById('add').onclick=()=>saveModal();document.getElementById('hero-add')?.addEventListener('click',()=>saveModal());document.getElementById('search').oninput=e=>{state.q=e.target.value;renderCards()};document.getElementById('city').onchange=e=>{state.city=e.target.value;state.district='';districtOptions();renderCards()};districtOptions();document.getElementById('district').onchange=e=>{state.district=e.target.value;renderCards()};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x===b));renderCards()});document.getElementById('sort').value=state.sort;document.getElementById('sort').onchange=e=>{state.sort=e.target.value;renderCards()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('cards').classList.toggle('list',state.view==='list');renderCards()});renderCards()}
function districtOptions(){let ds=[...new Set(data.filter(p=>(!state.city||p.city===state.city)&&p.district).map(p=>p.district))];document.getElementById('district').innerHTML='<option value="">所有鄉鎮市區</option>'+ds.map(d=>`<option ${d===state.district?'selected':''}>${esc(d)}</option>`).join('')}
function renderCards(){let rows=data.filter(p=>(state.page==='pending'?p.pending:state.page==='again'?p.again:!p.pending)&&(!state.city||p.city===state.city)&&(!state.district||p.district===state.district)&&(state.category==='全部'||p.cats.includes(state.category))&&(!state.q||[p.name,p.note,...p.notes.map(n=>n.text),p.myNote||''].join(' ').toLowerCase().includes(state.q.toLowerCase())));if(state.sort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name,'zh-TW'));document.getElementById('count').innerHTML=`共 <b>${rows.length}</b> 個${state.page==='pending'?'待補收藏':'好去處'}${state.city?' · '+esc(state.city):''}`;document.getElementById('cards').innerHTML=rows.length?rows.map(p=>`<button class="card" data-place="${p.id}"><div class="card-img">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}的情境示意照片" loading="lazy">`:`<div style="height:100%;display:grid;place-items:center;background:#e7ebdf;color:#94a281">${icon('link')}</div>`}<span class="tag">${icon(p.pending?'clock':catIcons[p.cats[0]])}${p.pending?'待補資料':esc(p.cats.join('・'))}</span><span class="save-flag">${icon('bookmark')}</span></div><div class="card-body"><div class="location">${icon('pin')}${esc(p.city)}${p.district?' · '+esc(p.district):''}</div><h3>${esc(p.name)}</h3><p class="card-note">${esc(p.myNote||p.note||'還沒有備註，寫下你的心動理由。')}</p><div class="card-footer"><span class="card-person"><span class="avatar">${esc(p.author.slice(-1))}</span>${esc(p.author)}收藏 · ${esc(p.date)}</span>${p.again?`<span class="visit">${icon('heart')} 想再去</span>`:p.visited?`<span class="visit">${icon('check')} 去過</span>`:`<span>${p.notes.length+(p.myNote?1:0)} 則備註</span>`}</div></div></button>`).join(''):`<div class="empty">${icon('search')}<h3>這裡還有位置，留給下一個好去處。</h3><p>試試其他關鍵字、地區或分類。</p><button class="secondary" id="reset-filter">清除篩選</button></div>`;document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.place)));document.getElementById('reset-filter')?.addEventListener('click',()=>{state.q='';state.city='';state.district='';state.category='全部';renderCollection()})}
function showOverlay(title,html,modal=false){document.getElementById('overlay').innerHTML=`<div class="overlay-bg"><section class="${modal?'modal':'drawer'}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-head"><h2>${title}</h2><button class="close" aria-label="關閉">${icon('close')}</button></div>${html}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.close').onclick=closeOverlay;document.querySelector('.overlay-bg').onclick=e=>{if(e.target===e.currentTarget)closeOverlay()};setTimeout(()=>document.querySelector('.close')?.focus(),30)}
function closeOverlay(){document.getElementById('overlay').innerHTML='';document.body.style.overflow=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlay();if(e.key==='Tab'&&document.querySelector('[role=dialog]')){let els=[...document.querySelector('[role=dialog]').querySelectorAll('button,a[href],input,select,textarea')].filter(x=>!x.disabled&&x.offsetParent!==null);let first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function detail(id){let p=data.find(x=>x.id===id);if(p.pending){saveModal(p);return}current=p;showOverlay('口袋裡的好去處',`${p.image?`<img class="detail-photo" src="${esc(p.image)}" alt="${esc(p.name)}情境示意照片">`:''}<div class="drawer-content"><div class="location">${icon('pin')}${esc(p.city)} · ${esc(p.district)}</div><h2 class="detail-title">${esc(p.name)}</h2><div class="detail-tags">${p.cats.map(c=>`<span class="pill">${esc(c)}</span>`).join('')}</div><div class="detail-info">${icon('pin')} ${esc(p.address||[p.city,p.district].join(''))}<br>由 ${esc(p.author)} 收藏於 ${esc(p.date)}</div><div class="detail-actions"><a class="primary" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+' '+p.city+' '+p.district)}">${icon('pin')} Google Maps 開啟</a><button class="secondary" id="edit">編輯地點</button></div><h3 class="block-title">大家的備註 <small>每個人的心得，各自保留</small></h3>${p.notes.map(n=>`<div class="note-box"><div class="person"><span class="avatar">${esc(n.name.slice(-1))}</span>${esc(n.name)}</div><p>${esc(n.text)}</p></div>`).join('')}<h3 class="block-title">我的紀錄 <small>只有你能編輯這份紀錄</small></h3><form id="my-note"><div class="checks"><label class="check"><input name="visited" type="checkbox" ${p.visited?'checked':''}>${icon('check')} 去過</label><label class="check"><input name="again" type="checkbox" ${p.again?'checked':''}>${icon('heart')} 想再去</label></div><label class="field"><span>你的心得 · 署名「你」</span><textarea name="note" placeholder="這裡最喜歡的是什麼？下次還想試試什麼？">${esc(p.myNote||'')}</textarea></label><button class="primary" type="submit">儲存我的紀錄</button></form><h3 class="block-title">收藏來源 <small>同一個地方，也能有不同的發現</small></h3>${p.links.length?p.links.map((l,i)=>`<a class="source-link" href="${esc(safeUrl(l))}" target="_blank" rel="noopener">${icon('link')} 來源連結 ${i+1} ↗<br>${esc(l)}</a>`).join(''):'<p class="detail-info">這筆收藏尚未加入來源連結。</p>'}<button class="secondary" id="add-source">${icon('plus')} 加入新連結與備註</button><p class="prototype">地點與備註為原型示範資料；照片為情境示意，出發前請確認實際地址及營業資訊。</p><button class="danger secondary" id="delete">刪除此收藏</button></div>`);document.getElementById('edit').onclick=()=>editModal(p);document.getElementById('add-source').onclick=()=>sourceModal(p);document.getElementById('my-note').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);p.myNote=f.get('note').trim();p.visited=f.has('visited');p.again=f.has('again');addUpdate(`你更新了「${p.name}」的個人紀錄`);render();toast('已儲存你的心得與狀態')};document.getElementById('delete').onclick=()=>{showOverlay('刪除收藏',`<div class="drawer-content"><p>確定刪除「${esc(p.name)}」及其所有連結與備註？</p><p class="prototype">你是本清單的管理員，可刪除收藏。一般成員僅能刪除自己新增的地點。</p><div class="form-footer"><button class="secondary" id="cancel-delete">保留收藏</button><button class="primary" id="confirm-delete">確認刪除</button></div></div>`,true);document.getElementById('cancel-delete').onclick=()=>detail(p.id);document.getElementById('confirm-delete').onclick=()=>{data=data.filter(x=>x.id!==p.id);addUpdate(`你刪除了「${p.name}」`);closeOverlay();render();toast('收藏已刪除')}}}
function safeUrl(v){try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function citySelect(value){return `<select name="city"><option value="">選擇縣市</option>${cities.map(c=>`<option ${value===c?'selected':''}>${c}</option>`).join('')}</select>`}
function catChecks(cats=[]){return `<div class="checks">${categories.map(c=>`<label class="check"><input type="checkbox" name="cats" value="${c}" ${cats.includes(c)?'checked':''}>${c}</label>`).join('')}</div>`}
function placeFields(p={}){return `<label class="field"><span>地點名稱 *</span><input name="name" value="${esc(p.pending?'':p.name||'')}" placeholder="例如：正好鮮肉小籠包" required></label><div class="row"><label class="field"><span>縣市 *</span>${citySelect(p.city)}</label><label class="field"><span>鄉鎮市區 *</span><input name="district" value="${esc(p.district||'')}" placeholder="例如：宜蘭市"></label></div><label class="field"><span>地址（選填）</span><input name="address" value="${esc(p.address||'')}" placeholder="補上詳細地址，更容易找到"></label><label class="field"><span>分類（可複選）*</span></label>${catChecks(p.cats)}`}
function editModal(p){showOverlay('編輯地點資料',`<div class="drawer-content"><p class="prototype">清單內所有成員都能修改地點資料。個人心得由本人編輯。</p><form id="edit-place">${placeFields(p)}<div class="form-footer"><button type="button" class="secondary" id="back-detail">取消</button><button class="primary">儲存修改</button></div></form></div>`);document.getElementById('back-detail').onclick=()=>detail(p.id);document.getElementById('edit-place').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);if(!validatePlace(f))return;Object.assign(p,{name:f.get('name').trim(),city:f.get('city'),district:f.get('district').trim(),address:f.get('address').trim(),cats:f.getAll('cats')});addUpdate(`你修改了「${p.name}」的地點資料`);render();detail(p.id);toast('地點資料已更新')}}
function validatePlace(f){if(!f.get('city')||!f.get('district').trim()||!f.getAll('cats').length){toast('請補上縣市、鄉鎮市區，並至少選一個分類');return false}return true}
function saveModal(p=null){showOverlay(p?.id?'整理這份收藏':'收藏一個好去處',`<div class="drawer-content"><div class="form-step">01 留下來源 → 02 確認地點 → 03 存入清單</div><div class="notice">${icon('link')} 把連結放進口袋，心動就不會忘記。<br>網頁原型目前由你手動確認地點；FB 自動辨識與 Android 分享入口尚待串接。</div><form id="save-place"><label class="field"><span>貼文或網頁連結</span><input type="url" name="url" placeholder="貼上 Facebook、部落格或其他網址" value="${esc(p?.links[0]||'')}"><small>可先存連結，稍後再補地點資料。</small></label><label class="field"><span>文字線索（選填）</span><textarea name="clue" placeholder="貼上店名、貼文文字，或先寫下你想去的原因">${esc(p?.note||'')}</textarea></label><label class="field"><span>補充截圖（選填）</span><input type="file" id="screenshot" accept="image/*"><small id="file-info">原型僅在本次整理時預覽截圖，不上傳、不自動辨識。</small></label><img id="screenshot-preview" alt="補充截圖預覽" style="display:none;width:100%;max-height:180px;object-fit:contain"><div class="block-title">確認地點資訊 <small>現在沒時間？先存連結就好</small></div>${placeFields(p||{})}<label class="field"><span>我的備註</span><textarea name="note" placeholder="推薦的餐點、想去的原因、出發前要注意的事…">${esc(p?.myNote||'')}</textarea></label><label class="field"><span>存入共用清單</span><select><option>🌿 週末出走計畫 · 4 位成員</option></select></label><label class="toggle-check"><input type="checkbox" id="whole-post"> 這是多地點貼文，先整篇收藏</label><div class="form-footer"><button type="button" class="secondary" id="save-later">先存連結，稍後整理</button><button type="button" class="primary" id="save-now">儲存收藏 ${icon('check')}</button></div><p class="prototype">多地點貼文可先整篇保存，或在儲存後選擇「沿用連結，新增下一個地點」逐一拆分。資料保存在目前瀏覽器。</p></form></div>`);let previewUrl;document.getElementById('screenshot').onchange=e=>{if(previewUrl)URL.revokeObjectURL(previewUrl);let file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('請選擇圖片檔案');return}previewUrl=URL.createObjectURL(file);let img=document.getElementById('screenshot-preview');img.src=previewUrl;img.style.display='block';document.getElementById('file-info').textContent=file.name+' · 僅供本次手動核對'};
const submit=pending=>{let form=document.getElementById('save-place'),f=new FormData(form),url=f.get('url').trim(),name=f.get('name').trim(),clue=f.get('clue').trim(),whole=document.getElementById('whole-post').checked;pending=pending||whole;if(url&&!safeUrl(url).startsWith('http')){toast('請輸入有效的 http 或 https 連結');return}if(pending&&!url){toast('先存連結需要填寫來源網址');form.elements.url.focus();return}if(!pending&&(!name||!validatePlace(f))){if(!name){toast('請填寫地點名稱');form.elements.name.focus()}return}
const existing=!pending&&data.find(x=>!x.pending&&x.id!==p?.id&&x.name.replace(/\s/g,'')===name.replace(/\s/g,'')&&x.city===f.get('city'));if(existing){showOverlay('這個地方已在口袋裡',`<div class="drawer-content"><div class="duplicate">${icon('bookmark')} 清單已有「${esc(existing.name)}」。<br>把這次發現的新連結和備註，一起加入原收藏。</div><div class="form-footer"><button class="secondary" id="dup-back">返回新增</button><button class="primary" id="merge">合併到原收藏</button></div></div>`,true);document.getElementById('dup-back').onclick=()=>saveModal({name,city:f.get('city'),district:f.get('district'),cats:f.getAll('cats'),note:clue,myNote:f.get('note'),links:url?[url]:[]});document.getElementById('merge').onclick=()=>{if(url&&!existing.links.includes(url))existing.links.push(url);let note=f.get('note').trim()||clue;if(note)existing.myNote=[existing.myNote,note].filter(Boolean).join('\n');if(p)data=data.filter(x=>x.id!==p.id);addUpdate(`你為「${existing.name}」加入新連結與備註`);closeOverlay();render();detail(existing.id);toast('已加入原收藏')};return}
const item={id:p?.id||Date.now(),name:pending?(name||clue.slice(0,24)||'新的貼文收藏'):name,city:f.get('city'),district:f.get('district').trim(),address:f.get('address').trim(),cats:f.getAll('cats'),pending,note:clue,myNote:f.get('note').trim(),author:p?.author||'你',date:p?.date||'11/13',links:url?[url]:[],notes:p?.notes||[],visited:p?.visited||false,again:p?.again||false,image:p?.image};if(p?.id){data=data.map(x=>x.id===p.id?item:x)}else data.unshift(item);addUpdate(`你${pending?'暫存':'收藏'}了「${item.name}」`);render();if(pending){closeOverlay();toast('已放入待補資料，之後再慢慢整理')}else{showOverlay('已放進我們的口袋',`<div class="drawer-content"><div class="profile-intro" style="color:#58744b">${icon('check')}<h2 style="font-family:'Noto Serif TC'">下一次出發，又多了一個理由。</h2><p>${esc(item.name)} 已存入週末出走計畫。</p></div><div class="form-footer"><button class="secondary" id="saved-detail">查看收藏</button><button class="primary" id="split-next">沿用連結，新增下一個地點</button></div></div>`,true);document.getElementById('saved-detail').onclick=()=>detail(item.id);document.getElementById('split-next').onclick=()=>saveModal({links:item.links,notes:[],city:item.city,cats:[]})}};document.getElementById('save-later').onclick=()=>submit(true);document.getElementById('save-now').onclick=()=>submit(false);document.getElementById('save-place').onsubmit=e=>{e.preventDefault();submit(false)}}
function sourceModal(p){showOverlay('加入新的發現',`<div class="drawer-content"><p class="detail-info">加入「${esc(p.name)}」的原收藏，讓好資訊留在一起。</p><form id="source-form"><label class="field"><span>來源連結 *</span><input type="url" name="url" required placeholder="https://…"></label><label class="field"><span>我的備註</span><textarea name="note" placeholder="這個連結有什麼值得記下來的？"></textarea></label><button class="primary">加入原收藏</button></form></div>`,true);document.getElementById('source-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),url=f.get('url').trim();if(safeUrl(url)==='#'){toast('請輸入有效連結');return}if(!p.links.includes(url))p.links.push(url);let note=f.get('note').trim();if(note)p.myNote=[p.myNote,note].filter(Boolean).join('\n');addUpdate(`你為「${p.name}」加入新發現`);detail(p.id);toast('已加入來源與備註')}}
function renderMembers(){document.getElementById('content').innerHTML=`<div class="page-intro"><div class="eyebrow">GOOD COMPANY, GREAT MEMORIES</div><h1>一起收藏，一起出發。</h1><p>週末出走計畫 · 你是清單管理員</p></div><div class="notice">此為共用權限的互動示範，尚未連接其他帳號。所有成員可編輯地點；新增者與管理員可刪除。每人的署名心得只由本人修改。</div><h3 class="block-title">加入申請 <small>須經管理員同意</small></h3>${requests.length?requests.map((n,i)=>`<div class="member-row"><span class="avatar">${esc(n.slice(-1))}</span><div><b>${esc(n)}</b><small>希望加入週末出走計畫 · 示範申請</small></div><button class="secondary" data-reject="${i}">婉拒</button><button class="primary" data-approve="${i}">同意</button></div>`).join(''):'<p class="detail-info">目前沒有待處理的加入申請。</p>'}<h3 class="block-title">清單成員 <small>示範成員</small></h3>${['你','小芸','阿哲','怡君'].map((n,i)=>`<div class="member-row"><span class="avatar">${n.slice(-1)}</span><div><b>${n}</b><small>${i===0?'管理員':'共同收藏成員'}</small></div><span class="pill">${i===0?'管理員':'可編輯地點'}</span></div>`).join('')}<button class="secondary" id="members-invite">${icon('people')} 邀請朋友加入</button>`;document.getElementById('members-invite').onclick=inviteModal;document.querySelectorAll('[data-approve],[data-reject]').forEach(b=>b.onclick=()=>{let approve=b.hasAttribute('data-approve'),i=Number(b.dataset.approve??b.dataset.reject),name=requests[i];requests.splice(i,1);addUpdate(`你${approve?'同意':'婉拒'}了${name}的加入申請（示範）`);render();toast(approve?'已示範核准加入流程':'已婉拒這次示範申請')})}
function renderUpdates(){document.getElementById('content').innerHTML=`<div class="page-intro"><div class="eyebrow">A LITTLE CLOSER TO OUR NEXT TRIP</div><h1>口袋裡的新鮮事。</h1><p>不打擾你的日常，打開時再看看大家的新發現。</p></div><div class="notice">${icon('leaf')} 不主動推播通知。這裡記錄本瀏覽器內的收藏與編輯更新。</div>${updates.map(u=>`<div class="update-row">${icon('bookmark')}<div>${esc(u.text)}<small>${esc(u.date)}</small></div></div>`).join('')}`}
function inviteModal(){showOverlay('好去處，找朋友一起收',`<div class="drawer-content"><div class="profile-intro">${icon('people')}<h2 style="font-family:'Noto Serif TC'">週末出走計畫</h2><p class="detail-info">朋友提出加入申請後，須經管理員同意。</p></div><div class="notice">邀請流程示範：目前沒有真實共用後端，以下操作只會在你的瀏覽器產生示範申請。</div><form id="invite-demo"><label class="field"><span>申請者暱稱</span><input name="name" placeholder="例如：小安" maxlength="20" required></label><button class="primary" style="width:100%">建立示範加入申請</button></form></div>`,true);document.getElementById('invite-demo').onsubmit=e=>{e.preventDefault();let n=new FormData(e.target).get('name').trim();if(!n){toast('請輸入暱稱');return}requests.push(n);persist();closeOverlay();state.page='members';render();toast('已建立示範申請，請由管理員審核')}}
function profileModal(){showOverlay('你的口袋',`<div class="drawer-content"><div class="profile-intro"><span class="avatar" style="width:58px;height:58px;font-size:22px">你</span><h2>嗨，週末想去哪裡？</h2><p class="detail-info">目前以示範管理員身分體驗</p></div><button class="google-button" id="google"><span class="google-g">G</span>Google 帳號登入 · 待串接</button><p class="prototype">正式版本將使用 Google 帳號登入。目前尚未設定 OAuth，不會收集你的 Google 帳號或密碼。</p><div class="notice">這是可操作的網頁原型。收藏、心得與整理進度儲存在目前瀏覽器，尚未跨裝置同步；FB 自動辨識、Android 分享和真實多人權限仍待開發。</div><button class="secondary" id="my-again" style="width:100%">${icon('heart')} 看看我的想再去清單</button></div>`,true);document.getElementById('google').onclick=()=>toast('Google 登入需要設定 OAuth，原型請使用示範身分');document.getElementById('my-again').onclick=()=>{closeOverlay();state.page='again';state.category='全部';state.city='';state.district='';state.q='';render()}}
render();
